import java.util.*;
public class Abood2D {
	static int N, fifty, hundred, K;
	static int[][][] memo;
	static int[][][][] memo2;
	static final int MOD = (int) 1e9 + 7;
	static long[][] comb;

	static int calc(int t, int f, int h) {
		if (f + h == 0) return 0;
		if (memo[t][f][h] != -1) return memo[t][f][h];
		if (t == 1) return 1 + (f < fifty ? calc(0, f + 1, h) : calc(0, f, h + 1));
		int res = (int) 1e6;
		for (int i = 0; i <= f; i++) {
			if (i * 50 > K) break;
			int j = Math.min((K - i * 50) / 100, h);
			int totalW = i * 50 + j * 100;
			if ((fifty - f + i > 0 && totalW > 50) || (hundred - h + j > 1 && totalW > 100) || (i == fifty && j == hundred))
				res = Math.min(res, calc(1, f - i, h - j));
		}
		return memo[t][f][h] = res + 1;
	}

	static int compute2(int t, int f, int h, int r) {
		if (r == 0 && f == 0 && h == 0) return 1;
		if (r == 0) return 0;
		if (memo2[t][f][h][r] != -1) return memo2[t][f][h][r];
		int answer = 0;
		if (t == 1) {
			for (int i = 0; i <= fifty - f; i++) {
				if (i * 50 > K) break;
				for (int j = 0; j <= hundred - h; j++) {
					if (i == 0 && j == 0) continue;
					int sumW = i * 50 + j * 100;
					if (sumW > K) break;
					answer = (int) ((answer + (long) (nCk(fifty - f, i) * nCk(hundred - h, j) % MOD) * compute2(0, f + i, h + j, r - 1)) % MOD);
				}
			}
		} else {
			for (int i = 0; i <= f; i++) {
				if (i * 50 > K) break;
				for (int j = 0; j <= h; j++) {
					if (i == 0 && j == 0) continue;
					int sumW = i * 50 + j * 100;
					if (sumW > K) break;
					answer = (int) ((answer + (long) (nCk(f, i) * nCk(h, j) % MOD) * compute2(1, f - i, h - j, r - 1)) % MOD);
				}
			}
		}
		return memo2[t][f][h][r] = answer;
	}

	static long nCk(int n, int k) {
		if (n < k) return 0;
		if (k == 0 || n == k) return 1;
		if (comb[n][k] != -1) return comb[n][k];
		if (n - k < k) return comb[n][k] = nCk(n, n - k);
		return comb[n][k] = (((long) n * nCk(n - 1, k - 1)) * pow(k, MOD - 2)) % MOD;
	}

	static int pow(int base, long exp) {
		int result = 1;
		while (exp > 0) {
			if ((exp & 1) == 1)
				result = (int) ((long) result * base % MOD);
			base = (int) ((long) base * base % MOD);
			exp >>= 1;
		}
		return result;
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int totalItems = sc.nextInt();
