import sys
import math

MOD = 10**9 + 7

def calc(t, f, h, fifty, hundred, K, memo):
    if f + h == 0:
        return 0
    if memo[t][f][h] != -1:
        return memo[t][f][h]
    if t == 1:
        if f < fifty:
            res = 1 + calc(0, f + 1, h, fifty, hundred, K, memo)
        else:
            res = 1 + calc(0, f, h + 1, fifty, hundred, K, memo)
        memo[t][f][h] = res
        return res
    res = int(1e6)
    for i in range(f + 1):
        if i * 50 > K:
            break
        j = min((K - i * 50) // 100, h)
        totalW = i * 50 + j * 100
        if ((fifty - f + i > 0 and totalW > 50) or
            (hundred - h + j > 1 and totalW > 100) or
            (i == fifty and j == hundred)):
            continue
        res = min(res, calc(1, f - i, h - j, fifty, hundred, K, memo))
    memo[t][f][h] = res + 1
    return memo[t][f][h]

def compute2(t, f, h, r, fifty, hundred, K, memo2, comb):
    if r == 0 and f == 0 and h == 0:
        return 1
    if r == 0:
        return 0
    if memo2[t][f][h][r] != -1:
        return memo2[t][f][h][r]
    answer = 0
    if t == 1:
        for i in range(fifty - f + 1):
            if i * 50 > K:
                break
            for j in range(hundred - h + 1):
                if i == 0 and j == 0:
                    continue
                sumW = i * 50 + j * 100
                if sumW > K:
                    break
                answer += (nCk(fifty - f, i, comb) * nCk(hundred - h, j, comb) % MOD) * compute2(0, f + i, h + j, r - 1, fifty, hundred, K, memo2, comb)
                answer %= MOD
    else:
        for i in range(f + 1):
            if i * 50 > K:
                break
            for j in range(h + 1):
                if i == 0 and j == 0:
                    continue
                sumW = i * 50 + j * 100
                if sumW > K:
                    break
                answer += (nCk(f, i, comb) * nCk(h, j, comb) % MOD) * compute2(1, f - i, h - j, r - 1, fifty, hundred, K, memo2, comb)
                answer %= MOD
    memo2[t][f][h][r] = answer
    return answer

def nCk(n, k, comb):
    if n < k:
        return 0
    if k == 0 or n == k:
        return 1
    if comb[n][k] != -1:
        return comb[n][k]
    if n - k < k:
        comb[n][k] = nCk(n, n - k, comb)
        return comb[n][k]
    comb[n][k] = (n * nCk(n - 1, k - 1, comb) * pow(k, MOD - 2, MOD)) % MOD
    return comb[n][k]

def main():
    input = sys.stdin.read().strip().split()
    totalItems = int(input[0])
    K = int(input[1])
    vals = list(map(int, input[2:]))

    fifty = 0
    hundred = 0
    for v in vals:
        if v == 50:
            fifty += 1
        elif v == 100:
            hundred += 1

    memo = [[[ -1 for _ in range(hundred + 1)] for _ in range(fifty + 1)] for _ in range(2)]
    comb = [[-1 for _ in range(101)] for _ in range(101)]
    for i in range(101):
        for j in range(101):
            comb[i][j] = -1

    minSteps = calc(0, fifty, hundred, fifty, hundred, K, memo)
    if minSteps >= 1e6:
        print(-1)
        print(0)
        return
    memo2 = [[[[ -1 for _ in range(int(minSteps) + 1)] for _ in range(hundred + 1)] for _ in range(fifty + 1)] for _ in range(2)]
    print(int(minSteps))
    print(compute2(0, fifty, hundred, int(minSteps), fifty, hundred, K, memo2, comb))

if __name__ == "__main__":
    main()

